import os,re,sys
root=sys.argv[1]
seeds=sys.argv[2:]
def path(mod):
    return os.path.join(root, mod.replace('.','/')+'.lean')
def imports(mod):
    p=path(mod)
    if not os.path.exists(p): return None
    out=[]
    for line in open(p,encoding='utf-8'):
        m=re.match(r'^import\s+(\S+)',line)
        if m: out.append(m.group(1))
        if line.startswith('/-!') or line.startswith('namespace'): pass
    return out
seen=set(); stack=list(seeds); missing=set()
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    im=imports(m)
    if im is None:
        missing.add(m); continue
    for i in im:
        if i.startswith('AlgebraicJacobian'): stack.append(i)
proj={m for m in seen if m.startswith('AlgebraicJacobian') and m not in missing}
print("PROJECT MODULES IN CLOSURE:", len(proj))
tot=0
for m in sorted(proj):
    n=sum(1 for _ in open(path(m),encoding='utf-8'))
    tot+=n
    print(f"{n:6d}  {m}")
print("TOTAL LINES:", tot)
